#!/usr/bin/env bash
# After a rollout, `rollout show HOST` names the release that just finished,
# for every active host.
. "$(dirname "$0")/lib.sh"
t_setup

rollout apply r2026.10.01 2>>"$T_WORK/apply.err"; assert_rc "baseline rollout completes" $? 0
for h in api-01 web-01 bat-02; do
  assert_contains "$h shows r2026.10.01" "$(rollout show "$h" 2>&1)" "r2026.10.01"
done

rollout apply r2026.10.08 2>>"$T_WORK/apply.err"; assert_rc "r2026.10.08 rollout completes" $? 0
for h in api-01 api-02 api-03 bat-01 bat-02 web-01 web-02; do
  assert_contains "$h shows r2026.10.08" "$(rollout show "$h" 2>&1)" "r2026.10.08"
done
assert_contains "web-01 settings unchanged" "$(rollout show web-01 2>&1)" "log_level = warn"
assert_contains "api-02 settings updated" "$(rollout show api-02 2>&1)" "pool_size = 40"
rollout show web-03 >/dev/null 2>&1
assert_rc "drained host still has no config" $? 1
t_done
# audit.sh — rollout history: one line per finished rollout.
# release|mark|hosts|changes

history_file() { printf '%s/history.log' "$OUT_DIR"; }

history_add() {
  ensure_dir "$OUT_DIR"
  printf '%s|%s|%s|%s\n' "$1" "$2" "$3" "$4" >> "$(history_file)"
}

history_show() {
  local f
  f=$(history_file)
  [ -f "$f" ] || return 0
  awk -F'|' '{ printf "%-14s %-9s %3s hosts %3s changes\n", $1, $2, $3, $4 }' "$f"
}
# common.sh — logging, configuration loading and small guards shared by
# the wrapper and every step script.

log()  { printf '[%s] %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; }
warn() { printf '[%s] warn: %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; }
die()  { printf '[%s] error: %s\n' "${ROLLOUT_STEP:-rollout}" "$*" >&2; exit "${2:-1}"; }

load_conf() {
  local f="$ROLLOUT_HOME/conf/rollout.conf"
  [ -r "$f" ] || die "missing config $f"
  # shellcheck disable=SC1090
  . "$f"
}

require_file() {
  [ -f "$1" ] || die "${2:-file} not found: $1"
  [ -r "$1" ] || die "${2:-file} not readable: $1"
}

ensure_dir() {
  mkdir -p "$1" 2>/dev/null || die "cannot create directory $1"
  [ -w "$1" ] || die "directory not writable: $1"
}

# Per-release working area: $WORK_DIR/<release id>
run_dir() { printf '%s/%s' "$WORK_DIR" "$1"; }

host_out() { printf '%s/hosts/%s/app.conf' "$OUT_DIR" "$1"; }

